impl Solution {
    pub fn merge_k_lists(lists: Vec<Option<Box<ListNode>>>) -> Option<Box<ListNode>> {
        let mut lists = lists;
        if lists.is_empty() {
            return None;
        }

        while lists.len() > 1 {
            let mut merged_lists = Vec::new();
            let mut i = 0;
            while i < lists.len() {
                let l1 = lists[i].take();
                let l2 = if i + 1 < lists.len() {
                    lists[i + 1].take()
                } else {
                    None
                };
                merged_lists.push(Self::merge_two_lists(l1, l2));
                i += 2;
            }
            lists = merged_lists;
        }
        lists.into_iter().next().flatten()
    }

    fn merge_two_lists(
        l1: Option<Box<ListNode>>,
        l2: Option<Box<ListNode>>,
    ) -> Option<Box<ListNode>> {
        let mut dummy = ListNode::new(0);
        let mut tail = &mut dummy;
        let mut l1 = l1;
        let mut l2 = l2;

        while l1.is_some() && l2.is_some() {
            let l1_val = l1.as_ref().unwrap().val;
            let l2_val = l2.as_ref().unwrap().val;

            if l1_val < l2_val {
                tail.next = l1.take();
                tail = tail.next.as_mut().unwrap();
                l1 = tail.next.take();
            } else {
                tail.next = l2.take();
                tail = tail.next.as_mut().unwrap();
                l2 = tail.next.take();
            }
        }

        if l1.is_some() {
            tail.next = l1;
        }
        if l2.is_some() {
            tail.next = l2;
        }

        dummy.next
    }
}

